/* ============ GROUPS: servers with categories, channels and roles ============
   A group is a server. Private groups are for schoolwork, friends and small teams. Official groups belong to a
   company or a school and carry its name; the verified badge shows once the organisation is verified.
   Every channel is a conversation in S.chats ({kind:'group', with: group id, ch: channel id}), so messages,
   widgets, pins, files and bot replies work the same everywhere.
   g = {id,name,desc,col,icon,kind,fig,mute,members,at, type:'private'|'official', owner, org:{name,kind,site,mail},
        verify:'none'|'pending'|'verified', avatar:fid, ban:{k,fid}, roles:[{id,name,col,perms,fixed}], mroles:{pid:[roleIds]},
        cats:[{id,name}], chs:[{id,name,type,cat,topic}], shut:[catIds], last, plugins:[], _v:2}
   Images live in IndexedDB under "g…" keys. Plugins are kept as an empty list for the plugin hub that comes later. */
const CHT={talk:['Talk','chat','var(--blue)','Conversation for everyone'],announce:['Announcements','bell','var(--accent)','Only chosen roles can post'],files:['Files','file','var(--green)','Upload, ask about and find files'],
 gallery:['Photos','image','var(--violet)','Photos, sketches and screenshots'],projects:['Projects','projects','var(--accent)','Only projects and their progress'],notes:['Notes','notes','var(--yellow)','Notes shared with the group'],
 ideas:['Ideas','idea','var(--yellow)','Post ideas, everyone votes'],events:['Plans','calendar','var(--blue)','Agendas, days and deadlines'],all:['Everything','board','var(--green)','Collects all that is attached, from every channel']};
const CHT_ORDER=['talk','announce','files','gallery','projects','notes','ideas','events','all'];
const GPERMS=[['manage','Manage the group','Name, pictures, verification'],['channels','Channels','Make, edit and sort channels'],['roles','Roles','Make roles and give them'],['announce','Announce','Post in announcement channels'],['pin','Pin','Pin messages'],['invite','Invite','Add and remove people']];
const RCOL=['var(--accent)','var(--blue)','var(--green)','var(--violet)','var(--yellow)','var(--red)'];
const BANS=[['thread','Thread'],['dots','Dots'],['rings','Rings'],['grid','Grid'],['wash','Wash'],['figure','Drawing']];
const OKINDS=[['company','Company'],['school','School']];
const gslug=s=>String(s||'').toLowerCase().trim().replace(/[^a-z0-9čšžćđ]+/g,'-').replace(/^-+|-+$/g,'').slice(0,32)||'channel';
const defRoles=()=>[{id:'owner',name:'Owner',col:'var(--accent)',perms:Object.fromEntries(GPERMS.map(p=>[p[0],true])),fixed:1},{id:'member',name:'Member',col:'var(--muted)',perms:{pin:true},fixed:1}];
function gFix(g){if(!g||g._v===2)return g;g.type=g.type||'private';g.owner=g.owner||'me';g.members=g.members||['me'];g.roles=g.roles||defRoles();g.mroles=g.mroles||{};
 g.cats=g.cats||[{id:'main',name:'Main'}];g.chs=g.chs||[{id:'general',name:'general',type:'talk',cat:'main',topic:'Talk about anything'},{id:'files',name:'files',type:'files',cat:'main',topic:'Files for everyone, and questions about them'}];
 g.ban=g.ban||{k:g.fig?'figure':'thread'};g.plugins=g.plugins||[];g.shut=g.shut||[];g.verify=g.verify||(g.type==='official'?'pending':'none');gRolesFix(g);g._v=2;return g}
function gRolesFix(g){g.members.forEach(m=>{if(!g.mroles[m]||!g.mroles[m].length)g.mroles[m]=[m===g.owner?'owner':'member']});Object.keys(g.mroles).forEach(m=>{if(!g.members.includes(m))delete g.mroles[m]})}
/* old saves: every group gets roles, a Main category with #general and #files, and its chat becomes #general */
function gFixAll(s){(s.groups||[]).forEach(g=>{gFix(g);(s.chats||[]).forEach(c=>{if(c.kind==='group'&&c.with===g.id&&!c.ch){const t=g.chs.find(x=>x.type==='talk')||g.chs[0];if(t)c.ch=t.id}})})}
const G=id=>gFix(grp(id));
const chanOf=c=>c&&c.kind==='group'&&c.ch?(G(c.with)?.chs||[]).find(x=>x.id===c.ch)||null:null;
function chanChat(g,ch){let c=S.chats.find(x=>x.kind==='group'&&x.with===g.id&&x.ch===ch.id);if(!c){c={id:uid(),kind:'group',with:g.id,ch:ch.id,msgs:[],read:Date.now(),at:Date.now()};S.chats.push(c)}return c}
function ensureGroupChat(gid,type){const g=G(gid);if(!g)return null;const ch=(type&&g.chs.find(x=>x.type===type))||g.chs.find(x=>x.type==='talk')||g.chs.find(x=>x.type!=='all')||g.chs[0];if(!ch){const n={id:'general',name:'general',type:'talk',cat:(g.cats[0]||{}).id||'main'};if(!g.cats.length)g.cats.push({id:'main',name:'Main'});g.chs.push(n);return chanChat(g,n)}return chanChat(g,ch)}
const gChats=g=>S.chats.filter(c=>c.kind==='group'&&c.with===g.id);
const gUnread=g=>gChats(g).reduce((a,c)=>a+unreadOf(c),0);
const rolesOf=(g,pid)=>(g.mroles[pid]||[]).map(r=>g.roles.find(x=>x.id===r)).filter(Boolean);
const topRole=(g,pid)=>g.roles.find(r=>(g.mroles[pid]||[]).includes(r.id))||g.roles.find(r=>r.id==='member');
function can(g,perm,pid='me'){if(!g)return false;if(g.owner===pid)return true;return rolesOf(g,pid).some(r=>r.perms&&r.perms[perm])}
function roleCol(c,pid){const g=G(c.with);if(!g)return'';const r=topRole(g,pid);return r&&r.id!=='member'?r.col:''}
const gVer=g=>g.verify==='verified'?`<span class="gver" title="Verified" aria-label="Verified">${ic('verified',1.8)}</span>`:g.type==='official'?`<span class="gpend">Pending</span>`:'';
const gLine=g=>g.type==='official'?`${(OKINDS.find(o=>o[0]===g.org?.kind)||OKINDS[0])[1]} · ${esc(g.org?.name||g.name)}`:`Private · ${gKind(g)}`;
const chPostable=(g,ch)=>ch.type!=='all'&&ch.type!=='projects'&&(ch.type!=='announce'||can(g,'announce'));
/* banner art: a thread, dots, rings, a grid, a wash, or the group's drawing; or an uploaded picture */
function gBanner(g,cls=''){const b=g.ban||{k:'thread'};if(b.fid)return`<div class="gban gbimg ${cls}" style="--gc:${g.col}"><img data-fid="${b.fid}" alt=""></div>`;
 const k=b.k||'thread',art=k==='thread'?`<svg viewBox="0 0 400 120" preserveAspectRatio="xMidYMid slice"><path d="M-10 80C60 30 110 110 180 64S300 20 410 56"/><path d="M-10 96C70 52 130 124 200 82S320 40 410 76" opacity=".55"/><path d="M-10 46C50 16 120 70 190 40S320 4 410 30" opacity=".3"/><circle cx="352" cy="44" r="5"/></svg>`
  :k==='rings'?`<svg viewBox="0 0 400 120" preserveAspectRatio="xMidYMid slice"><circle cx="330" cy="70" r="26"/><circle cx="330" cy="70" r="48" opacity=".55"/><circle cx="330" cy="70" r="72" opacity=".3"/><circle cx="330" cy="70" r="98" opacity=".15"/></svg>`
  :k==='figure'?`<span class="gbfig">${figure(g.fig||'team',{acc:g.col})}</span>`:'';
 return`<div class="gban b-${k} ${cls}" style="--gc:${g.col}">${art}</div>`}

/* ---------- the Groups tab ---------- */
function gTile(g){const u=gUnread(g),cs=gChats(g),lm=cs.map(c=>({c,m:lastMsg(c)})).filter(x=>x.m).sort((a,b)=>b.m.at-a.m.at)[0],lch=lm?chanOf(lm.c):null;
 return`<a class="card gtile ${g.type==='official'?'off':''}" href="#g:${g.id}" style="--gc:${g.col}">${gBanner(g,'sm')}<div class="gtb">${gAv(g,'lg ring')}<div class="grow"><b class="gtn">${esc(g.name)}${gVer(g)}${g.mute?`<span class="mutei" aria-label="Quiet">${ic('bell',1.8)}</span>`:''}</b><div class="sub sm">${gLine(g)}</div></div>${u?`<b class="badge">${u>99?'99+':u}</b>`:''}</div>
 <div class="gtc">${g.chs.filter(x=>x.type!=='all').slice(0,3).map(x=>`<span class="chp mini" style="--cc:${(CHT[x.type]||CHT.talk)[2]}"><span class="chh">#</span><span class="chn">${esc(x.name)}</span></span>`).join('')}${g.chs.length>3?`<span class="sub sm">+${g.chs.length-3}</span>`:''}</div>
 <div class="row between gtf">${avStack(g.members,5,24)}<span class="sub sm">${lm&&lch?`#${esc(lch.name)} · ${ago(lm.m.at)}`:plural(g.members.length,'member')}</span></div></a>`}
const gLast=g=>Math.max(g.at||0,...gChats(g).map(c=>lastMsg(c)?.at||0));
function pGroups(){const L=S.groups.map(gFix).sort((a,b)=>gLast(b)-gLast(a)),off=L.filter(g=>g.type==='official'),pri=L.filter(g=>g.type!=='official'),comm=!S.groups.some(g=>g.comm)&&S.people.some(p=>p.bot);
 return`<div class="page">${header('Groups',{sub:'Servers for teams and classes',right:`<a class="btn sm" href="#plugins">${ic('plug',2)} Plugins</a><button class="btn primary sm" onclick="groupForm()">${ic('plus',2)} New</button>`})}${chatTabs('groups')}
 ${L.length?`${off.length?`<section><div class="sh"><h2>Official</h2><span class="sub">${off.length}</span></div><div class="gtiles">${off.map(gTile).join('')}</div></section>`:''}
 ${pri.length?`<section><div class="sh"><h2>Private</h2><span class="sub">${pri.length}</span></div><div class="gtiles">${pri.map(gTile).join('')}</div></section>`:''}`
 :empty('team','Ideas grow in company','Make a group with channels for talking, files and projects. Add people, give roles and share anything.',`<button class="btn primary" onclick="groupForm()">New group</button>`)}
 ${comm?`<section><div class="sh"><h2>Discover</h2></div><div class="card gdisc" style="--gc:var(--accent)">${gBanner({col:'var(--accent)',ban:{k:'thread'}},'sm')}<div class="gtb">${gAv({col:'var(--accent)',icon:'star'},'lg ring')}<div class="grow"><b class="gtn">Atelier Community<span class="gver" aria-label="Verified">${ic('verified',1.8)}</span></b><div class="sub sm">Official · Atelier</div></div></div><p class="sub">Tips, ideas and show and tell with the Atelier team.</p><button class="btn primary sm" onclick="joinCommunity()">${ic('plus',2)} Join</button></div></section>`:''}</div>`}
function joinCommunity(){const bots=S.people.filter(p=>p.bot);if(!bots.length||S.groups.some(g=>g.comm))return;const owner=bots[0].id,id=uid();
 const g={id,comm:true,name:'Atelier Community',desc:'Tips, ideas and show and tell with the Atelier team.',col:'var(--accent)',icon:'star',kind:'club',fig:'team',members:['me',...bots.map(b=>b.id)],at:Date.now(),
  type:'official',owner,org:{name:'Atelier',kind:'company',site:'atelier.app'},verify:'verified',ban:{k:'thread'},roles:[...defRoles(),{id:'team',name:'Atelier team',col:'var(--violet)',perms:{announce:true,pin:true,invite:true}}],mroles:{},
  cats:[{id:'start',name:'Start here'},{id:'talk',name:'Talk'}],chs:[{id:'welcome',name:'welcome',type:'announce',cat:'start',topic:'News from the Atelier team'},{id:'all',name:'everything',type:'all',cat:'start',topic:'Everything shared in the community'},{id:'general',name:'general',type:'talk',cat:'talk',topic:'Say hello'},{id:'ideas',name:'ideas',type:'ideas',cat:'talk',topic:'What should Atelier do next?'},{id:'show',name:'show-your-work',type:'gallery',cat:'talk',topic:'Share what you made'}],plugins:[],shut:[],_v:2};
 bots.slice(1,3).forEach(b=>g.mroles[b.id]=['team']);S.groups.push(g);gRolesFix(g);
 const w=chanChat(g,g.chs[0]);w.msgs.push({id:uid(),from:owner,text:`Welcome to the community, ${S.me.name.split(' ')[0]}! Start in #general, and post ideas in #ideas.`,at:Date.now()});
 const i=chanChat(g,g.chs[3]);i.msgs.push({id:uid(),from:bots[1%bots.length].id,text:'A weekly review that sums up my focus and notes',at:Date.now()-3600e3,votes:[owner]});
 use('group_join');led('group','Joined Atelier Community',{ref:'g:'+id});save();go('g:'+id);burst('var(--accent)')}

/* ---------- inside a group: channels | channel | members ---------- */
function chPill(g,x,on){const cc=S.chats.find(c=>c.kind==='group'&&c.with===g.id&&c.ch===x.id),u=cc?unreadOf(cc):0,t=CHT[x.type]||CHT.talk;
 return`<a class="chp ${on?'on':''} ${u?'unr':''}" href="#g:${g.id}:${x.id}" style="--cc:${t[2]}"><span class="chh">#</span><span class="chn">${esc(x.name)}</span>${x.type!=='talk'?`<span class="cht" aria-label="${t[0]}">${ic(t[1],1.8)}</span>`:''}${u?`<b class="badge">${u>99?'99+':u}</b>`:''}</a>`}
function chPanel(g,ch){const cm=can(g,'channels');
 return`<div class="svhd">${gBanner(g,'sv')}<div class="svid">${gAv(g,'lg ring')}<div class="grow"><b>${esc(g.name)}${gVer(g)}</b><span class="sub sm">${gLine(g)}</span></div><a class="icon-btn sm" href="#group:${g.id}" aria-label="Group settings">${ic('gear')}</a></div></div>
 <div class="svcats">${g.cats.map(cat=>{const L=g.chs.filter(x=>x.cat===cat.id),shut=g.shut.includes(cat.id);return`<div class="svcat ${shut?'shut':''}"><div class="svcath"><button type="button" onclick="catToggle('${g.id}','${cat.id}')" aria-expanded="${!shut}">${ic('category',2.2)}<span>${esc(cat.name)}</span></button>${cm?`<button type="button" class="svadd" onclick="channelForm('${g.id}',null,'${cat.id}')" aria-label="New channel in ${esc(cat.name)}">${ic('plus',2.2)}</button>`:''}</div>
  <div class="svlist">${L.map(x=>chPill(g,x,ch&&x.id===ch.id)).join('')||`<span class="sub sm svnone">No channels yet</span>`}</div></div>`}).join('')}</div>
 ${cm?`<div class="svnew"><button type="button" class="btn sm" onclick="channelForm('${g.id}')">${ic('hash',2)} Channel</button><button type="button" class="btn sm" onclick="catForm('${g.id}')">${ic('plus',2)} Category</button></div>`:''}
 <a class="svplug" href="#group:${g.id}">${ic('plug',1.8)}<div class="grow"><b>Plugins</b><span class="sub sm">${(g.plugins||[]).length?(g.plugins||[]).map(i=>esc(plugOf(i.pid)?.name||'')).filter(Boolean).slice(0,3).join(', '):'Add welcome messages, coins and more'}</span></div>${ic('chevr')}</a>`}
function catToggle(gid,cid){const g=G(gid);g.shut=g.shut.includes(cid)?g.shut.filter(x=>x!==cid):[...g.shut,cid];saveSoon();const el=$('#svCh');if(el){const s=el.scrollTop;el.innerHTML=chPanel(g,g.chs.find(x=>x.id===g.last));el.scrollTop=s;loadImgs(el)}}
function memRow(g,m){const p=person(m);if(!p)return'';const r=topRole(g,m),rs=rolesOf(g,m).filter(x=>x.id!=='member');
 return`<button type="button" class="svm" onclick="memberSheet('${g.id}','${m}')">${avatar(p,32)}<div class="grow"><b style="${r&&r.id!=='member'?`color:${r.col}`:''}">${esc(m==='me'?(S.me.name.split(' ')[0]+' (you)'):p.name)}</b><span class="sub sm">${rs.length?rs.map(x=>esc(x.name)).join(', '):p.bot?'Teammate':'Member'}</span></div>${m===g.owner?`<span class="svcrown" aria-label="Owner">${ic('crown',1.8)}</span>`:''}</button>`}
function memPanel(g){const f=g.roles.some(r=>r.id===window._rf)?window._rf:'all',used=g.roles.filter(r=>g.members.some(m=>(g.mroles[m]||[]).includes(r.id)));const seen=new Set();
 return`<div class="svmh"><b>Members</b><span class="sub sm">${g.members.length}</span><span class="grow"></span>${can(g,'invite')?`<button type="button" class="icon-btn sm" onclick="groupForm('${g.id}')" aria-label="Add people">${ic('addp')}</button>`:''}</div>
 <div class="chips rfil">${[['all','All'],...used.map(r=>[r.id,r.name])].map(([k,n])=>`<button type="button" class="chip ${f===k?'on':''}" onclick="window._rf='${k}';svMem('${g.id}')">${esc(n)}</button>`).join('')}</div>
 ${g.roles.map(r=>{const L=g.members.filter(m=>!seen.has(m)&&topRole(g,m)?.id===r.id&&(f==='all'||(g.mroles[m]||[]).includes(f)));L.forEach(m=>seen.add(m));return L.length?`<div class="svrole"><div class="svrh" style="--rc:${r.col}"><i></i>${esc(r.name)}<span>${L.length}</span></div>${L.map(m=>memRow(g,m)).join('')}</div>`:''}).join('')}${typeof botRows==='function'?botRows(g):''}`}
function svMem(gid){const el=$('#svMem');if(el)el.innerHTML=memPanel(G(gid))}
function svToggle(side){const b=document.body,k=side==='l'?'svl':'svr';const on=!b.classList.contains(k);b.classList.remove('svl','svr');if(on)b.classList.add(k)}
function svClose(){document.body.classList.remove('svl','svr')}
/* what sits above the messages, by channel type */
function chShelf(g,ch,c){const t=ch.type;
 if(t==='files'){const {ph,fl}=mediaOf(c),L=[...fl.filter(m=>m.att.kind==='doc').map(m=>({m,k:'doc'})),...ph.map(m=>({m,k:'photo'}))].sort((a,b)=>b.m.at-a.m.at);
  return`<div class="svshelf"><div class="svsh-h"><b>${ic('file',1.9)} Files here</b><span class="sub sm">${L.length}</span><label class="btn sm">${ic('upload',2)} Upload<input type="file" multiple hidden onchange="chUpload('${c.id}',this.files)"></label></div>${L.length?`<div class="fgrid">${L.slice(0,6).map(({m,k})=>k==='photo'?`<button type="button" class="ftile mthumb" onclick="viewAtt('${c.id}','${m.id}')" aria-label="Open photo"><img data-fid="${m.att.fid}" alt=""></button>`:`<button type="button" class="ftile" onclick="viewAtt('${c.id}','${m.id}')"><span class="mth" style="--mc:var(--green)">${ic('file',1.7)}<i>${esc(((m.att.title||'').split('.').pop()||'FILE').toUpperCase().slice(0,4))}</i></span><b>${esc(m.att.title||'File')}</b><span class="sub sm">${fmtSize(m.att.size||0)}</span></button>`).join('')}</div>`:`<p class="sub sm">Upload a file and the whole group can open it, ask about it and find it later.</p>`}</div>`}
 if(t==='gallery'){const {ph}=mediaOf(c);return`<div class="svshelf"><div class="svsh-h"><b>${ic('image',1.9)} Photos</b><span class="sub sm">${ph.length}</span><label class="btn sm">${ic('plus',2)} Add<input type="file" accept="image/*" multiple hidden onchange="chUpload('${c.id}',this.files)"></label></div>${ph.length?`<div class="mgrid">${ph.slice(0,8).map(m=>`<button type="button" class="mthumb" onclick="viewAtt('${c.id}','${m.id}')" aria-label="Open photo"><img data-fid="${m.att.fid}" alt=""></button>`).join('')}</div>`:`<p class="sub sm">Photos, sketches and screenshots collect here.</p>`}</div>`}
 if(t==='projects'){const ps=S.projects.filter(p=>(p.groups||[]).includes(g.id));return`<div class="svshelf"><div class="svsh-h"><b>${ic('projects',1.9)} Group projects</b><span class="sub sm">${ps.length}</span></div>${activeProj(ps)}</div>`}
 if(t==='notes'){const ns=S.notes.filter(n=>n.share.groups.includes(g.id)).sort((a,b)=>b.up-a.up);return`<div class="svshelf"><div class="svsh-h"><b>${ic('notes',1.9)} Shared notes</b><span class="sub sm">${ns.length}</span><button type="button" class="btn sm" onclick="chNote('${c.id}')">${ic('plus',2)} Share</button></div>${ns.length?`<div class="ngrid">${ns.slice(0,4).map((n,k)=>noteCard(n,k)).join('')}</div>`:`<p class="sub sm">Share a note and it stays here for everyone, with its arrows and sketches.</p>`}</div>`}
 if(t==='ideas'){const L=c.msgs.filter(m=>!m.att&&m.text).sort((a,b)=>(b.votes||[]).length-(a.votes||[]).length).slice(0,3).filter(m=>(m.votes||[]).length);return L.length?`<div class="svshelf"><div class="svsh-h"><b>${ic('star',1.9)} Top ideas</b></div><div class="card list flat">${L.map((m,i)=>`<div class="li tidea"><span class="tin">${i+1}</span><div class="grow t">${esc(m.text)}</div><span class="vote on">${ic('vote',1.8)}<b>${m.votes.length}</b></span></div>`).join('')}</div></div>`:''}
 if(t==='events')return`<div class="svshelf svquick"><button type="button" class="btn sm" onclick="openWidget('${c.id}','agenda',agendaAtt(today()))">${ic('calendar',2)} Share today's agenda</button><button type="button" class="btn sm" onclick="openWidget('${c.id}','day',dayAtt(today()))">${ic('sun',2)} Share my day</button><button type="button" class="btn sm" onclick="openWidget('${c.id}','countdown')">${ic('flag',2)} Countdown</button></div>`;
 return''}
/* the Everything channel: one feed of all that was attached, in every channel */
function gFeed(g){const out=[];gChats(g).forEach(c=>{const ch=chanOf(c);if(!ch)return;c.msgs.forEach(m=>{if(m.att)out.push({c,ch,m})})});return out.sort((a,b)=>b.m.at-a.m.at)}
const FEEDF=[['all','All'],['photo','Photos'],['file','Files'],['note','Notes'],['project','Projects'],['widget','Widgets']];
function feedKind(a){return a.kind==='photo'?'photo':a.kind==='doc'||a.kind==='file'?'file':a.kind==='note'?'note':a.kind==='project'||a.kind==='progress'?'project':isWidget(a)?'widget':'file'}
function feedRow(g,{c,ch,m}){const a=m.att,k=feedKind(a),who=m.from==='me'?'You':person(m.from)?.name.split(' ')[0]||'';
 const open=a.kind==='photo'||a.kind==='doc'?`viewAtt('${c.id}','${m.id}')`:a.kind==='note'&&note(a.id)?`go('note:${a.id}')`:(a.kind==='project'||a.kind==='progress')&&proj(a.id)?`go('project:${a.id}')`:`go('g:${g.id}:${ch.id}')`;
 return`<button type="button" class="li svfr" onclick="${open}">${a.kind==='photo'?`<span class="mthumb sm"><img data-fid="${a.fid}" alt=""></span>`:`<span class="fic" style="color:${(CHT[ch.type]||CHT.talk)[2]}">${a.kind==='note'?noteGlyph():ic(isWidget(a)?(WKINDS.find(w=>w[0]===a.kind)||[0,0,'star'])[2]:(ATT[a.kind]||ATT.file)[1])}</span>`}<div class="grow"><div class="t">${esc(a.title||(isWidget(a)?wLabel(a)+' widget':'Attachment'))}</div><div class="sub sm"><span class="chp mini" style="--cc:${(CHT[ch.type]||CHT.talk)[2]}"><span class="chh">#</span><span class="chn">${esc(ch.name)}</span></span> ${esc(who)} · ${ago(m.at)}</div></div></button>`}
function feedHtml(g){const f=window._af||'all',L=gFeed(g).filter(x=>f==='all'||feedKind(x.m.att)===f);
 return`<div class="chips svff">${FEEDF.map(([k,n])=>`<button type="button" class="chip ${f===k?'on':''}" onclick="window._af='${k}';render()">${n}</button>`).join('')}</div>
 ${L.length?`<div class="card list svfeed">${L.slice(0,120).map(x=>feedRow(g,x)).join('')}</div>`:`<div class="card emptyrow sub">${f==='all'?'Photos, files, notes, projects and widgets from every channel collect here.':'Nothing like that yet.'}</div>`}`}
function chWelcome(g,ch){const t=CHT[ch.type]||CHT.talk;return`<div class="chwel" style="--cc:${t[2]}"><span class="chbig">#</span><h3>Welcome to #${esc(ch.name)}</h3><p class="sub">${esc(ch.topic||t[3])}</p><span class="chtype">${ic(t[1],1.8)} ${t[0]} channel</span></div>`}
function chComposer(g,ch,c){const t=ch.type;
 if(t==='all')return'';
 if(t==='announce'&&!can(g,'announce')){const who=g.roles.filter(r=>r.perms&&r.perms.announce).map(r=>r.name);return`<div class="composer svlock">${ic('lock',1.9)}<span>Only ${esc(who.join(' and ')||'the owner')} can post in #${esc(ch.name)}.</span></div>`}
 if(t==='projects')return`<div class="composer svact"><button type="button" class="btn grow" onclick="chProject('${c.id}')">${ic('projects',2)} Share a project</button><button type="button" class="btn primary grow" onclick="projectForm({groups:['${g.id}']})">${ic('plus',2)} New project</button></div>`;
 const clip=t==='files'?`<label class="icon-btn" aria-label="Upload files">${ic('attach')}<input type="file" multiple hidden onchange="chUpload('${c.id}',this.files)"></label>`:t==='gallery'?`<label class="icon-btn" aria-label="Add photos">${ic('image')}<input type="file" accept="image/*" multiple hidden onchange="chUpload('${c.id}',this.files)"></label>`:t==='notes'?`<button type="button" class="icon-btn" onclick="chNote('${c.id}')" aria-label="Share a note">${ic('notes')}</button>`:`<button type="button" class="icon-btn" onclick="attachSheet('${c.id}')" aria-label="Share">${ic('attach')}</button>`;
 return`<form class="composer" id="cf">${clip}<input id="ci" placeholder="${t==='ideas'?'Post an idea in':'Message'} #${esc(ch.name)}" autocomplete="off" enterkeyhint="send" maxlength="2000"><button class="sendb" aria-label="Send">${ic('send',2)}</button></form>`}
function pServer(gid,chId){svClose();const g=G(gid);if(!g)return redirect('groups');
 let ch=g.chs.find(x=>x.id===chId)||g.chs.find(x=>x.id===g.last)||g.chs.find(x=>x.type!=='all')||g.chs[0];
 if(ch&&g.last!==ch.id){g.last=ch.id;saveSoon()}const c=ch&&ch.type!=='all'?chanChat(g,ch):null;window._svc=c?c.id:null;if(c&&unreadOf(c)){c.read=Date.now();saveSoon()}
 const t=ch?CHT[ch.type]||CHT.talk:CHT.talk,pins=c?pinsOf(c):[],nAtt=c?c.msgs.filter(m=>m.att).length:0;
 after(()=>{const f=$('#cf'),i=$('#ci');if(f&&c){f.onsubmit=e=>{e.preventDefault();const v=i.value;if(!v.trim())return;i.value='';i.classList.remove('cmdin');cmdPop(g,'');const m=sendMsg(c,v);appendMsgs(c);if(ch.type==='ideas'&&m)botsVote(c,m)};i.addEventListener('input',()=>{cmdPop(g,i.value);i.classList.toggle('cmdin',i.value.startsWith('/'))});if(!('ontouchstart' in window)&&innerWidth>=900)i.focus()}
  if(c){msgPress($('#msgs'),c);scrollChat(false)}if(!window._svU){window._svU=1;use('channel_open')}});
 const body=!ch?`<div class="chwel"><span class="chbig">#</span><h3>No channels yet</h3><p class="sub">Channels are where everything happens.</p>${can(g,'channels')?`<button class="btn primary" onclick="channelForm('${g.id}')">New channel</button>`:''}</div>`
  :ch.type==='all'?`${chWelcome(g,ch)}${feedHtml(g)}`
  :`<div class="msgs" id="msgs">${(()=>{const lim=c._lim||80,st=Math.max(0,c.msgs.length-lim);return(st?`<button class="btn sm earlier" onclick="const c=S.chats.find(x=>x.id==='${c.id}');c._lim=(c._lim||80)+200;render()">Show earlier messages</button>`:chWelcome(g,ch))+c.msgs.slice(st).map((m,k)=>msgHtml(c,m,c.msgs[st+k-1],st+k)).join('')})()}<div class="typing" id="typ" hidden><span></span><span></span><span></span></div></div>`;
 return`<div class="page convop srvp" style="--gc:${g.col};--cc:${t[2]}">
 <aside class="svpanel svch" id="svCh" aria-label="Channels">${chPanel(g,ch)}</aside>
 <section class="svmain"><header class="ph chath svh"><a class="icon-btn" href="#groups" aria-label="Back to groups">${ic('back')}</a><button type="button" class="svgb" onclick="svToggle('l')" aria-label="Channels of ${esc(g.name)}">${gAv(g,'sm')}${gUnread(g)?'<i class="svdot"></i>':''}</button>
  <div class="grow svtt"><b><span class="chh">#</span>${esc(ch?ch.name:g.name)}</b><span class="sub sm">${esc(g.name)}${ch?' · '+t[0]:''}</span></div>
  ${c?`<button type="button" class="icon-btn" onclick="attachedSheet('${c.id}')" aria-label="Attached in this channel">${ic('folder')}${nAtt?`<i class="ibn">${nAtt>99?'99+':nAtt}</i>`:''}</button>`:''}<button type="button" class="icon-btn svmb" onclick="svToggle('r')" aria-label="Members">${ic('members')}</button>
  ${pins.length?`<button type="button" class="pinbar" onclick="attachedSheet('${c.id}')">${ic('pin',2)}<div class="grow"><b>Pinned${pins.length>1?' · '+pins.length:''}</b><span>${esc(msgPreview({...pins[0],from:'x'}))}</span></div>${ic('chevr')}</button>`:''}</header>
  <div class="svscroll" id="svS">${ch&&c?chShelf(g,ch,c):''}${body}</div>${ch&&c?chComposer(g,ch,c):''}</section>
 <aside class="svpanel svmem" id="svMem" aria-label="Members">${memPanel(g)}</aside><div class="svscrim" onclick="svClose()"></div></div>`}
/* channel actions */
async function chUpload(cid,list){const c=S.chats.find(x=>x.id===cid);const L=[...(list||[])];if(!c||!L.length)return;let n=0;
 for(const f of L){if(f.size>25*1048576){toast(f.name+' is over 25 MB');continue}const fid='c'+uid();try{await IDB.put(fid,f)}catch(e){toast('Could not save '+f.name);continue}
  sendMsg(c,'',{kind:f.type.startsWith('image/')?'photo':'doc',fid,title:f.name||'Photo',type:f.type,size:f.size});n++}
 if(n){if(onChat(c))render();toast(n>1?`${n} files shared`:'Shared')}}
function chNote(cid){const c=S.chats.find(x=>x.id===cid),g=G(c.with);pickList('Share a note',S.notes.slice().sort((a,b)=>b.up-a.up).map(n=>({id:n.id,html:`${noteGlyph(NCOL[(n.col||0)%NCOL.length])}<div class="grow"><div class="t">${esc(noteTitle(n))}</div><div class="sub sm">${ago(n.up)}</div></div>`})),id=>{closeSheet();const n=note(id);if(!n.share.groups.includes(g.id)){n.share.groups.push(g.id);use('note_share')}sendMsg(c,'',noteAtt(n));render()},'Write a note first')}
function chProject(cid){const c=S.chats.find(x=>x.id===cid),g=G(c.with);pickList('Share a project',S.projects.map(p=>({id:p.id,html:`<span class="fic" style="color:${p.col}">${ic('projects')}</span><div class="grow"><div class="t">${esc(p.name)}</div><div class="sub sm">${pctOf(p)}% done</div></div>`})),id=>{closeSheet();const p=proj(id);p.groups=p.groups||[];if(!p.groups.includes(g.id))p.groups.push(g.id);sendMsg(c,'',projAtt(p));render()},'Make a project first')}
function attachedSheet(cid){const c=S.chats.find(x=>x.id===cid),ch=chanOf(c);if(!c)return;openModal(`<div class="sheet" role="dialog" aria-modal="true" aria-label="Attached"><div class="sheet-h"><h2>Attached in #${esc(ch?ch.name:'')}</h2><button class="icon-btn" data-close aria-label="Close">${ic('close')}</button></div>${infoMedia(c,18)}</div>`);loadImgs($('#modal'))}
/* ideas: everyone votes, bots too */
function msgExtra(c,m){const ch=chanOf(c);if(!ch||ch.type!=='ideas'||m.att||!m.text)return'';const v=m.votes||[];return`<button type="button" class="vote ${v.includes('me')?'on':''}" data-vote="${c.id}|${m.id}" aria-label="Vote">${ic('vote',1.8)}<b>${v.length}</b></button>`}
document.addEventListener('click',e=>{const b=e.target.closest('[data-vote]');if(!b)return;e.preventDefault();e.stopPropagation();const [cid,mid]=b.dataset.vote.split('|'),c=S.chats.find(x=>x.id===cid),m=c?.msgs.find(x=>x.id===mid);if(!m)return;
 m.votes=m.votes||[];const on=!m.votes.includes('me');m.votes=on?[...m.votes,'me']:m.votes.filter(x=>x!=='me');if(on)use('idea_vote');save();b.classList.toggle('on',on);b.querySelector('b').textContent=m.votes.length;b.classList.remove('pop');void b.offsetWidth;b.classList.add('pop')},true);
function botsVote(c,m){const g=G(c.with);if(!g)return;g.members.filter(id=>id!=='me'&&person(id)?.bot).slice(0,4).forEach((id,i)=>setTimeout(()=>{if(Math.random()<.7&&!(m.votes||[]).includes(id)){m.votes=[...(m.votes||[]),id];save();const b=document.querySelector(`[data-vote="${c.id}|${m.id}"]`);if(b){b.querySelector('b').textContent=m.votes.length;b.classList.remove('pop');void b.offsetWidth;b.classList.add('pop')}}},1400+i*1100))}
/* a member: roles, message, remove */
function memberSheet(gid,pid){const g=G(gid),p=person(pid);if(!p)return;const rg=can(g,'roles'),rs=rolesOf(g,pid);
 openModal(`<div class="sheet" role="dialog" aria-modal="true" aria-label="${esc(p.name)}"><div class="sheet-h"><h2>${esc(pid==='me'?'You':p.name)}</h2><button class="icon-btn" data-close aria-label="Close">${ic('close')}</button></div>
 <div class="msh">${avatar(p,64)}<div><b>${esc(pid==='me'?fullName():p.name)}</b><div class="sub">${esc(roleOf(p)||(p.bot?'Teammate bot':''))}</div><div class="rchips">${rs.map(r=>`<span class="rchip" style="--rc:${r.col}"><i></i>${esc(r.name)}</span>`).join('')}</div></div></div>
 ${rg&&pid!==g.owner?`<div class="flabel">Roles</div><div class="picks">${g.roles.filter(r=>r.id!=='owner').map(r=>`<label class="pickrow"><input type="checkbox" data-r="${r.id}" ${(g.mroles[pid]||[]).includes(r.id)?'checked':''}><span class="gdot" style="background:${r.col}"></span><b>${esc(r.name)}</b><span class="sub sm">${GPERMS.filter(x=>r.perms&&r.perms[x[0]]).map(x=>x[1]).join(', ')||'Can talk'}</span></label>`).join('')}</div>`:''}
 <div class="row mt">${pid!=='me'?`<button class="btn grow" id="mDM">${ic('chat')} Message</button>`:''}${can(g,'invite')&&pid!==g.owner&&pid!=='me'?`<button class="btn grow danger" id="mRm">Remove</button>`:''}</div></div>`);
 $$('[data-r]').forEach(b=>b.onchange=()=>{const L=new Set(g.mroles[pid]||[]);if(b.checked)L.add(b.dataset.r);else L.delete(b.dataset.r);if(!L.size)L.add('member');g.mroles[pid]=[...L];use('role_give');save();svMem(gid);if(b.checked){const r=g.roles.find(x=>x.id===b.dataset.r);if(r)plugOnRole(g,pid,r.name)}});
 const dm=$('#mDM');if(dm)dm.onclick=()=>{closeSheet();const c=ensureDM(pid);save();go('c:'+c.id)};
 const rm=$('#mRm');if(rm)rm.onclick=()=>{closeSheet();setTimeout(()=>ask(`Remove ${esc(p.name).replace(/'/g,'')} from ${esc(g.name)}?`,()=>{g.members=g.members.filter(x=>x!==pid);gRolesFix(g);use('group_edit')},'Remove'),220)}}

/* ---------- making and editing a group ---------- */
function groupForm(id,type){const g=id?G(id):null;
 if(!g&&!type){openModal(`<div class="sheet" role="dialog" aria-modal="true" aria-label="New group"><div class="sheet-h"><h2>New group</h2><button class="icon-btn" data-close aria-label="Close">${ic('close')}</button></div><p class="sub" style="margin:0 2px 12px">What kind of group is it?</p>
  <div class="gtype"><button type="button" data-t="private" style="--gc:var(--blue)"><span class="gtic">${ic('lock',1.8)}</span><b>Private group</b><span>For schoolwork, friends and small teams. Only people you add can join.</span></button>
  <button type="button" data-t="official" style="--gc:var(--accent)"><span class="gtic">${ic('verified',1.8)}</span><b>Official group</b><span>For a company or a school. It carries the organisation's name and, once verified, the badge.</span></button></div></div>`);
  $$('.gtype [data-t]').forEach(b=>b.onclick=()=>{closeSheet();setTimeout(()=>groupForm(null,b.dataset.t),200)});return}
 const T=g?g.type:type,off=T==='official',col=g?g.col:GCOL[S.groups.length%GCOL.length],icon=g?.icon||(off?'case':'group'),kind=g?.kind||'team',fig=g?.fig||'team',bk=g?.ban?.fid?'upload':(g?.ban?.k||'thread'),ok=g?.org?.kind||'company';
 let avFile=null,banFile=null,avDrop=false,banDrop=false;
 sheet(g?'Edit group':off?'New official group':'New private group',`<div class="gform-pv" id="gPv" style="--gc:${col}"><div id="gPvB">${gBanner(g||{col,ban:{k:bk==='upload'?'thread':bk},fig},'pv')}</div><div class="gtb">${'<span id="gPvA">'+gAv(g||{col,icon},'lg ring')+'</span>'}<div class="grow"><b class="gtn" id="gPvN">${esc(g?.name||'New group')}</b><div class="sub sm" id="gPvK">${off?'Official':'Private'}</div></div></div></div>
 <label for="gN">Name</label><input id="gN" name="name" required maxlength="40" value="${esc(g?.name||'')}" placeholder="${off?'e.g. Northside High':'e.g. Physics study group'}"><label for="gD">What is it for?</label><input id="gD" name="desc" maxlength="140" value="${esc(g?.desc||'')}" placeholder="Short description">
 ${off?`<div class="flabel">Organisation</div><div class="seg" id="gOK">${OKINDS.map(([k,n])=>`<label><input type="radio" name="okind" value="${k}" ${ok===k?'checked':''}><span>${n}</span></label>`).join('')}</div>
 <label for="gON">Organisation name</label><input id="gON" name="oname" maxlength="60" value="${esc(g?.org?.name||'')}" placeholder="The official name"><label for="gOS">Website</label><input id="gOS" name="osite" maxlength="80" inputmode="url" value="${esc(g?.org?.site||'')}" placeholder="example.com"><label for="gOM">Contact email</label><input id="gOM" name="omail" type="email" maxlength="80" value="${esc(g?.org?.mail||'')}" placeholder="name@example.com">`
 :`<div class="flabel">Kind</div><div class="seg wrap2" id="gK">${GKINDS.map(([k,n])=>`<label><input type="radio" name="kind" value="${k}" ${kind===k?'checked':''}><span>${n}</span></label>`).join('')}</div>`}
 <div class="flabel">Picture</div><div class="opts gicons">${GICONS.map(i=>`<label class="swl"><input type="radio" name="icon" value="${i}" ${icon===i&&!g?.avatar?'checked':''}><span class="gico">${ic(i)}</span></label>`).join('')}<label class="swl gup"><input type="file" accept="image/*" id="gAvF" hidden><span class="gico">${ic('upload')}</span></label></div>
 <div class="flabel">Colour</div><div class="opts">${GCOL.map(c=>`<label class="swl"><input type="radio" name="col" value="${c}" ${col===c?'checked':''}><span class="sw" style="background:${c}"></span></label>`).join('')}</div>
 <div class="flabel">Banner</div><div class="banpick">${BANS.map(([k,n])=>`<label class="swl"><input type="radio" name="ban" value="${k}" ${bk===k?'checked':''}><span class="bano">${gBanner({col,ban:{k},fig},'opt')}<em>${n}</em></span></label>`).join('')}<label class="swl"><input type="radio" name="ban" value="upload" ${bk==='upload'?'checked':''}><span class="bano bup">${ic('upload',1.8)}<em>Upload</em></span><input type="file" accept="image/*" id="gBnF" hidden></label></div>
 <div class="flabel">Drawing</div><div class="figpick">${GFIGS.map(f=>`<label class="swl"><input type="radio" name="fig" value="${f}" ${fig===f?'checked':''}><span class="figo">${figure(f,{acc:col})}</span></label>`).join('')}</div>
 <label class="chk"><input type="checkbox" name="mute" ${g?.mute?'checked':''}> Quiet: no pop-up messages from this group</label>
 ${!g||can(g,'invite')?`<div class="flabel">Members</div>${memberPicker(g?g.members:[])}`:''}`,fd=>{const name=fd.name.trim();if(!name){toast('Name the group');return false}
  if(off&&!String(fd.oname||'').trim()){toast('Add the organisation name');return false}
  const mem=!g||can(g,'invite')?[...new Set(['me',...(g?[g.owner]:[]),...S.people.filter(p=>fd['m_'+p.id]).map(p=>p.id)])].filter(x=>x==='me'||person(x)):g.members;
  const o={name,desc:fd.desc.trim(),col:fd.col,icon:GICONS.includes(fd.icon)?fd.icon:(g?.icon||'group'),kind:off?(fd.okind==='school'?'class':'team'):(fd.kind||'team'),fig:GFIGS.includes(fd.fig)?fd.fig:'team',mute:!!fd.mute,members:mem,ban:{k:fd.ban==='upload'?(g?.ban?.k||'thread'):(fd.ban||'thread'),fid:fd.ban==='upload'?(g?.ban?.fid||null):null}};
  if(off)o.org={name:String(fd.oname).trim(),kind:fd.okind==='school'?'school':'company',site:String(fd.osite||'').trim().replace(/^https?:\/\//,'').replace(/\/$/,''),mail:String(fd.omail||'').trim()};
  let tg=g;if(g){const was=[...g.members];if(g.ban?.fid&&!o.ban.fid)IDB.del(g.ban.fid).catch(()=>{});Object.assign(g,o);gRolesFix(g);use('group_edit');const added=g.members.filter(m=>!was.includes(m));if(added.length)setTimeout(()=>plugOnJoin(g,added),300)}
  else{tg=gFix({id:uid(),at:Date.now(),type:T,owner:'me',verify:off?'pending':'none',...o});S.groups.push(tg);tg.chs.forEach(x=>chanChat(tg,x));use('group_new');if(off)use('group_verify');led('group',`Created ${off?'official':'private'} group ${name}`,{ref:'g:'+tg.id});setTimeout(()=>{go('g:'+tg.id);burst(fd.col)},60)}
  const put=async(file,fn)=>{const fid='g'+uid();try{await IDB.put(fid,file);fn(fid);save();render()}catch(e){toast('Could not save the picture')}};
  if(avFile)put(avFile,fid=>{if(tg.avatar)IDB.del(tg.avatar).catch(()=>{});tg.avatar=fid});else if(avDrop&&tg.avatar){IDB.del(tg.avatar).catch(()=>{});tg.avatar=null}
  if(banFile&&fd.ban==='upload')put(banFile,fid=>{if(tg.ban.fid)IDB.del(tg.ban.fid).catch(()=>{});tg.ban.fid=fid})},
 g?(g.owner==='me'?`<button type="button" class="btn danger full" onclick="groupDelete('${g.id}')">Delete group</button>`:`<button type="button" class="btn danger full" onclick="groupLeave('${g.id}')">Leave group</button>`):'');
 const f=$('#sf');const prev=()=>{const c=f.col.value,k=f.ban.value;$('#gPv').style.setProperty('--gc',c);$('#gPvN').textContent=f.name.value.trim()||'New group';
  if(!avFile){$('#gPvA').innerHTML=gAv({col:c,icon:f.icon.value||icon,avatar:avDrop?null:g?.avatar},'lg ring');loadImgs($('#gPvA'))}
  if(k!=='upload'){$('#gPvB').innerHTML=gBanner({col:c,ban:{k},fig:f.fig.value},'pv')}else if(!banFile&&g?.ban?.fid){$('#gPvB').innerHTML=gBanner({col:c,ban:{fid:g.ban.fid}},'pv');loadImgs($('#gPvB'))}
  f.querySelectorAll('.figo').forEach(el=>el.querySelectorAll('g')[1]?.setAttribute('stroke',c));f.querySelectorAll('.bano .gban').forEach(el=>el.style.setProperty('--gc',c))};
 f.addEventListener('change',e=>{if(e.target.name==='icon'){avDrop=true;avFile=null}prev()});$('#gN').addEventListener('input',prev);
 $('#gAvF').onchange=e=>{const fl=e.target.files[0];if(!fl)return;avFile=fl;f.querySelectorAll('[name=icon]').forEach(x=>x.checked=false);$('#gPvA').innerHTML=`<span class="gav lg ring gimgav"><img src="${URL.createObjectURL(fl)}" alt=""></span>`};
 $('#gBnF').onchange=e=>{const fl=e.target.files[0];if(!fl)return;banFile=fl;f.querySelector('[name=ban][value=upload]').checked=true;$('#gPvB').innerHTML=`<div class="gban gbimg pv"><img src="${URL.createObjectURL(fl)}" alt=""></div>`};
 f.querySelector('.bup').addEventListener('click',e=>{e.preventDefault();$('#gBnF').click()});loadImgs($('#gPv'))}
function groupDrop(g){const gone=gChats(g);S.chats=S.chats.filter(c=>!(c.kind==='group'&&c.with===g.id));gone.forEach(c=>c.msgs.forEach(m=>dropBlob(m.att)));
 if(g.avatar)IDB.del(g.avatar).catch(()=>{});if(g.ban?.fid)IDB.del(g.ban.fid).catch(()=>{});S.groups=S.groups.filter(x=>x.id!==g.id);S.projects.forEach(p=>p.groups=(p.groups||[]).filter(x=>x!==g.id));S.notes.forEach(n=>n.share.groups=n.share.groups.filter(x=>x!==g.id))}
function groupDelete(gid){const g=G(gid);closeSheet();setTimeout(()=>ask(`Delete ${esc(g.name).replace(/'/g,'')}?`,()=>{groupDrop(g);go('groups')}),220)}
function groupLeave(gid){const g=G(gid);closeSheet();setTimeout(()=>ask(`Leave ${esc(g.name).replace(/'/g,'')}?`,()=>{groupDrop(g);go('groups')},'Leave'),220)}
/* channels and categories */
function channelForm(gid,chId,catId){const g=G(gid),ch=chId?g.chs.find(x=>x.id===chId):null;if(!can(g,'channels')){toast('You need the Channels role for this');return}const tp=ch?.type||'talk';
 sheet(ch?'Edit channel':'New channel',`<div class="chpv" id="chPv"><span class="chp on" style="--cc:${CHT[tp][2]}"><span class="chh">#</span><span class="chn" id="chPvN">${esc(ch?.name||'new-channel')}</span></span></div>
 <label for="chN">Name</label><input id="chN" name="name" required maxlength="32" value="${esc(ch?.name||'')}" placeholder="e.g. homework" autocomplete="off">
 <div class="flabel">Type</div><div class="chtypes">${CHT_ORDER.map(k=>{const t=CHT[k];return`<label style="--cc:${t[2]}"><input type="radio" name="type" value="${k}" ${tp===k?'checked':''}><span class="cht-i">${ic(t[1],1.8)}</span><b>${t[0]}</b><span>${t[3]}</span></label>`}).join('')}</div>
 <label for="chC">Category</label><select id="chC" name="cat">${g.cats.map(c=>`<option value="${c.id}" ${(ch?.cat||catId||g.cats[0]?.id)===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}<option value="__new">New category…</option></select>
 <label for="chT">Topic</label><input id="chT" name="topic" maxlength="100" value="${esc(ch?.topic||'')}" placeholder="What is this channel for?">`,fd=>{const name=gslug(fd.name);let cat=fd.cat;
  if(cat==='__new'){cat='k'+uid();g.cats.push({id:cat,name:'New category'})}
  if(ch){Object.assign(ch,{name,type:CHT[fd.type]?fd.type:'talk',cat,topic:fd.topic.trim()});use('group_edit')}
  else{const n={id:'h'+uid(),name,type:CHT[fd.type]?fd.type:'talk',cat,topic:fd.topic.trim()};g.chs.push(n);g.shut=g.shut.filter(x=>x!==cat);if(n.type!=='all')chanChat(g,n);use('channel_new');led('group',`New channel #${name} in ${g.name}`,{ref:'g:'+g.id+':'+n.id});setTimeout(()=>go('g:'+g.id+':'+n.id),60)}},
 ch&&g.chs.length>1?`<button type="button" class="btn danger full" onclick="channelDelete('${gid}','${ch.id}')">Delete channel</button>`:'');
 const f=$('#sf'),pv=()=>{$('#chPvN').textContent=gslug(f.name.value||'new-channel');$('#chPv .chp').style.setProperty('--cc',CHT[f.type.value]?.[2]||'var(--blue)')};f.addEventListener('input',pv);f.addEventListener('change',pv)}
function channelDelete(gid,chId){const g=G(gid),ch=g.chs.find(x=>x.id===chId);closeSheet();setTimeout(()=>ask(`Delete #${esc(ch.name)}? Its messages go too.`,()=>{const c=S.chats.find(x=>x.kind==='group'&&x.with===gid&&x.ch===chId);g.chs=g.chs.filter(x=>x.id!==chId);if(c){S.chats=S.chats.filter(x=>x!==c);c.msgs.forEach(m=>dropBlob(m.att))}if(g.last===chId)g.last=null;go('g:'+gid)}),220)}
function catForm(gid,catId){const g=G(gid),cat=catId?g.cats.find(x=>x.id===catId):null;
 sheet(cat?'Edit category':'New category',`<label for="ctN">Name</label><input id="ctN" name="name" required maxlength="30" value="${esc(cat?.name||'')}" placeholder="e.g. Homework">`,fd=>{const name=fd.name.trim();if(!name)return false;if(cat)cat.name=name;else g.cats.push({id:'k'+uid(),name});use('group_edit')},
 cat&&g.cats.length>1?`<button type="button" class="btn danger full" onclick="catDelete('${gid}','${cat.id}')">Delete category</button>`:'')}
function catDelete(gid,catId){const g=G(gid);closeSheet();setTimeout(()=>ask('Delete this category? Its channels move to the first one.',()=>{g.cats=g.cats.filter(x=>x.id!==catId);const to=g.cats[0].id;g.chs.forEach(x=>{if(x.cat===catId)x.cat=to})},'Delete'),220)}
/* roles */
function roleForm(gid,rid){const g=G(gid),r=rid?g.roles.find(x=>x.id===rid):null;if(!can(g,'roles')){toast('You need the Roles role for this');return}const col=r?.col||RCOL[g.roles.length%RCOL.length],own=r?.id==='owner';
 sheet(r?'Edit role':'New role',`<div class="rpv" id="rPv" style="--rc:${col}"><span class="rchip big"><i></i><b id="rPvN">${esc(r?.name||'New role')}</b></span></div>
 <label for="rN">Name</label><input id="rN" name="name" required maxlength="24" value="${esc(r?.name||'')}" placeholder="e.g. Moderator">
 <div class="flabel">Colour</div><div class="opts">${RCOL.map(c=>`<label class="swl"><input type="radio" name="col" value="${c}" ${col===c?'checked':''}><span class="sw" style="background:${c}"></span></label>`).join('')}</div>
 <div class="flabel">What it can do</div><div class="picks">${GPERMS.map(([k,n,d])=>`<label class="pickrow"><input type="checkbox" name="p_${k}" ${own||r?.perms?.[k]?'checked':''} ${own?'disabled':''}><b>${n}</b><span class="sub sm">${d}</span></label>`).join('')}</div>
 ${own?'':`<div class="flabel">Members with this role</div><div class="picks">${g.members.filter(m=>m!==g.owner&&person(m)).map(m=>`<label class="pickrow"><input type="checkbox" name="m_${m}" ${(g.mroles[m]||[]).includes(r?.id)?'checked':''}>${avatar(person(m),28)}<b>${esc(m==='me'?'You':person(m).name)}</b></label>`).join('')||'<p class="sub">Add people to the group first.</p>'}</div>`}`,fd=>{const name=fd.name.trim();if(!name)return false;
  const perms=own?r.perms:Object.fromEntries(GPERMS.map(([k])=>[k,!!fd['p_'+k]]));let role=r;if(r)Object.assign(r,{name,col:fd.col,perms});else{role={id:'r'+uid(),name,col:fd.col,perms};g.roles.splice(Math.max(1,g.roles.length-1),0,role);use('role_new');led('group',`New role ${name} in ${g.name}`,{ref:'group:'+g.id})}
  if(!own&&role.id!=='member')g.members.forEach(m=>{if(m===g.owner)return;const L=new Set(g.mroles[m]||[]),had=L.has(role.id);if(fd['m_'+m])L.add(role.id);else L.delete(role.id);if(!L.size)L.add('member');g.mroles[m]=[...L];if(!had&&fd['m_'+m])setTimeout(()=>plugOnRole(g,m,role.name),200)})},
 r&&!r.fixed?`<button type="button" class="btn danger full" onclick="roleDelete('${gid}','${r.id}')">Delete role</button>`:'');
 const f=$('#sf');f.addEventListener('input',()=>{$('#rPvN').textContent=f.name.value.trim()||'New role'});f.addEventListener('change',()=>$('#rPv').style.setProperty('--rc',f.col.value))}
function roleDelete(gid,rid){const g=G(gid);closeSheet();setTimeout(()=>ask('Delete this role?',()=>{g.roles=g.roles.filter(x=>x.id!==rid);Object.keys(g.mroles).forEach(m=>{g.mroles[m]=g.mroles[m].filter(x=>x!==rid)});gRolesFix(g)}),220)}
/* official groups: the verification request */
function verifyForm(gid){const g=G(gid);if(g.owner!=='me'){toast('Only the owner can ask for verification');return}
 sheet(g.type==='official'?'Verification':'Make it official',`<p class="sub" style="margin-top:0">Official groups belong to a company or a school. They carry its name, sit at the top of Groups and, once verified, show the badge.</p>
 <div class="seg">${OKINDS.map(([k,n])=>`<label><input type="radio" name="okind" value="${k}" ${(g.org?.kind||'company')===k?'checked':''}><span>${n}</span></label>`).join('')}</div>
 <label for="vN">Organisation name</label><input id="vN" name="oname" required maxlength="60" value="${esc(g.org?.name||'')}"><label for="vS">Website</label><input id="vS" name="osite" maxlength="80" inputmode="url" value="${esc(g.org?.site||'')}" placeholder="example.com"><label for="vM">Contact email</label><input id="vM" name="omail" type="email" maxlength="80" value="${esc(g.org?.mail||'')}" placeholder="name@example.com">`,fd=>{const n=String(fd.oname||'').trim();if(!n){toast('Add the organisation name');return false}
  const was=g.type;g.type='official';g.org={name:n,kind:fd.okind==='school'?'school':'company',site:String(fd.osite||'').trim().replace(/^https?:\/\//,'').replace(/\/$/,''),mail:String(fd.omail||'').trim()};if(g.verify!=='verified')g.verify='pending';use('group_verify');if(was!=='official')led('group',`${g.name} is now an official group`,{ref:'group:'+g.id});toast('Request saved')})}
function verifyCard(g){if(g.type!=='official')return g.owner==='me'?`<div class="card gvcard"><div class="lab" style="--lc:var(--accent)">${ic('verified',2)}<span>Official</span></div><p class="sub">Is this group for a company or a school? Make it official to carry its name and get verified.</p><button class="btn sm" onclick="verifyForm('${g.id}')">Make it official</button></div>`:'';
 const o=g.org||{},dom=(o.site||'').toLowerCase().replace(/^www\./,''),md=(o.mail||'').toLowerCase().split('@')[1]||'',steps=[['Organisation name',!!o.name],['Website',!!dom],['Email at the website',!!dom&&!!md&&(md===dom||md.endsWith('.'+dom))]];
 return`<div class="card gvcard ${g.verify}"><div class="lab" style="--lc:${g.verify==='verified'?'var(--blue)':'var(--accent)'}">${ic('verified',2)}<span>${g.verify==='verified'?'Verified':'Verification'}</span></div>
 <b class="gvn">${esc(o.name||g.name)}</b><div class="sub sm">${(OKINDS.find(x=>x[0]===o.kind)||OKINDS[0])[1]}${dom?' · '+esc(dom):''}</div>
 ${g.verify==='verified'?`<p class="sub">This group is verified. Its badge shows next to its name everywhere.</p>`:`<div class="gvsteps">${steps.map(([n,ok])=>`<div class="${ok?'ok':''}">${ic(ok?'check':'close',2)}<span>${n}</span></div>`).join('')}</div><p class="sub">Your request is saved and ready. Atelier checks it once group accounts go online, and the badge appears when it is confirmed.</p>`}
 ${g.owner==='me'&&g.verify!=='verified'?`<button class="btn sm" onclick="verifyForm('${g.id}')">${ic('edit')} Edit details</button>`:''}</div>`}
/* the group's own page: everything about it, and its settings */
function groupMedia(g){const cs=gChats(g),pins=[],ph=[],fl=[];cs.forEach(c=>c.msgs.forEach(m=>{if(m.pin)pins.push({c,m});const a=m.att;if(!a)return;if(a.kind==='photo')ph.push({c,m});else if(['doc','file','note'].includes(a.kind))fl.push({c,m})}));[pins,ph,fl].forEach(L=>L.sort((a,b)=>b.m.at-a.m.at));const cap=window._mcap||9;
 return`<section><div class="sh"><h2>Pinned</h2><span class="sub">${pins.length}</span></div>${pins.length?`<div class="card list">${pins.slice(0,8).map(({c,m})=>`<a class="li" href="#c:${c.id}"><span class="fic">${ic(m.att?(ATT[m.att.kind]||ATT.file)[1]:'pin')}</span><div class="grow"><div class="t">${esc(msgPreview({...m,from:'x'}))}</div><div class="sub sm">#${esc(chanOf(c)?.name||'')} · ${esc(m.from==='me'?'You':person(m.from)?.name||'')} · ${fmtDay(m.at)}</div></div></a>`).join('')}</div>`:`<div class="card emptyrow sub">Press and hold a message in a channel to pin it.</div>`}</section>
 <section><div class="sh"><h2>Photos</h2><span class="sub">${ph.length}</span></div>${ph.length?`<div class="mgrid">${ph.slice(0,cap).map(({c,m})=>`<button type="button" class="mthumb" onclick="viewAtt('${c.id}','${m.id}')" aria-label="Open photo"><img data-fid="${m.att.fid}" alt="" decoding="async"></button>`).join('')}</div>${ph.length>cap?`<button class="btn full" onclick="window._mcap=(window._mcap||9)+18;render()">All ${ph.length} photos</button>`:''}`:`<div class="card emptyrow sub">Photos shared in any channel show up here.</div>`}</section>
 <section><div class="sh"><h2>Files</h2><span class="sub">${fl.length}</span></div>${fl.length?`<div class="card list">${fl.slice(0,12).map(({c,m})=>{const a=m.att;return a.kind==='doc'?`<button class="li" onclick="viewAtt('${c.id}','${m.id}')"><span class="fic">${ic('file')}</span><div class="grow"><div class="t">${esc(a.title)}</div><div class="sub sm">#${esc(chanOf(c)?.name||'')} · ${fmtSize(a.size||0)} · ${fmtDay(m.at)}</div></div></button>`:`<a class="li" href="#${a.kind==='note'?'note:'+a.id:'project:'+a.pid+':files'}"><span class="fic">${a.kind==='note'?noteGlyph():ic('file')}</span><div class="grow"><div class="t">${esc(a.title)}</div><div class="sub sm">#${esc(chanOf(c)?.name||'')} · ${a.kind==='note'?'Note':'Project file'} · ${fmtDay(m.at)}</div></div></a>`}).join('')}</div>`:`<div class="card emptyrow sub">Files and notes shared in any channel show up here.</div>`}</section>`}
function pGroup(id){const g=G(id);if(!g){return redirect('groups')}const ps=S.projects.filter(p=>(p.groups||[]).includes(id)),ns=S.notes.filter(n=>n.share.groups.includes(id)),u=gUnread(g),mg=can(g,'manage'),cm=can(g,'channels'),rm=can(g,'roles');
 return`<div class="page ginfo" style="--gc:${g.col}">${header(esc(g.name),{sub:g.type==='official'?'Official group':'Private group',back:'g:'+id,right:mg?`<button class="btn sm" onclick="groupForm('${id}')">${ic('edit')} Edit</button>`:''})}
 <div class="card ghero2">${gBanner(g,'lg')}<div class="gh2">${gAv(g,'xl ring')}<div class="grow"><h2>${esc(g.name)}${gVer(g)}</h2><span class="sub">${gLine(g)}</span></div></div><p>${esc(g.desc||'A group with channels for everything.')}</p>
  <div class="row wrap"><a class="btn primary sm" href="#g:${id}">${ic('hash')} Open${u?` · ${u}`:''}</a><button class="btn sm" onclick="projectForm({groups:['${id}']})">${ic('projects')} New project</button><button class="btn sm ${g.mute?'on':''}" onclick="const g=grp('${id}');g.mute=!g.mute;use('group_edit');save();render();toast(g.mute?'Quiet: no pop-ups':'Pop-ups on')">${ic('bell')} ${g.mute?'Quiet':'Alerts on'}</button></div></div>
 ${verifyCard(g)}
 <section><div class="sh"><h2>Members</h2><span class="sub">${g.members.length}</span></div><div class="mstrip">${g.members.map(m=>{const p=person(m),r=topRole(g,m);return p?`<button class="mem" onclick="memberSheet('${id}','${m}')">${avatar(p,52)}<b>${esc(m==='me'?'You':p.name.split(' ')[0])}</b><span style="${r&&r.id!=='member'?`color:${r.col}`:''}">${esc(r&&r.id!=='member'?r.name:roleOf(p)||(p.bot?'Teammate':''))}</span></button>`:''}).join('')}${can(g,'invite')?`<button class="mem add" onclick="groupForm('${id}')"><span class="addc">${ic('addp',1.8)}</span><b>Add</b><span>people</span></button>`:''}</div></section>
 <section><div class="sh"><h2>Roles</h2>${rm?`<button class="lnk" onclick="roleForm('${id}')">New role</button>`:''}</div><div class="card list">${g.roles.map(r=>{const n=g.members.filter(m=>(g.mroles[m]||[]).includes(r.id)).length;return`<button class="li" ${rm?`onclick="roleForm('${id}','${r.id}')"`:'disabled'}><span class="rdot" style="--rc:${r.col}">${ic(r.id==='owner'?'crown':'shield',1.8)}</span><div class="grow"><div class="t">${esc(r.name)}</div><div class="sub sm">${r.id==='owner'?'Can do everything':GPERMS.filter(x=>r.perms&&r.perms[x[0]]).map(x=>x[1]).join(', ')||'Can talk and share'}</div></div><span class="sub sm">${plural(n,'member')}</span></button>`}).join('')}</div></section>
 <section><div class="sh"><h2>Channels</h2>${cm?`<button class="lnk" onclick="channelForm('${id}')">New channel</button>`:''}</div>${g.cats.map(cat=>`<div class="gchcat"><div class="gchh"><span>${esc(cat.name)}</span>${cm?`<button class="lnk sm" onclick="catForm('${id}','${cat.id}')">Edit</button>`:''}</div><div class="card list">${g.chs.filter(x=>x.cat===cat.id).map(x=>{const t=CHT[x.type]||CHT.talk;return`<div class="li gchrow"><a class="chp" href="#g:${id}:${x.id}" style="--cc:${t[2]}"><span class="chh">#</span><span class="chn">${esc(x.name)}</span></a><span class="sub sm grow">${t[0]}</span>${cm?`<button class="icon-btn sm" onclick="channelForm('${id}','${x.id}')" aria-label="Edit #${esc(x.name)}">${ic('edit')}</button>`:''}</div>`}).join('')||'<div class="li sub sm">No channels</div>'}</div></div>`).join('')}${cm?`<button class="btn sm" onclick="catForm('${id}')">${ic('plus',2)} New category</button>`:''}</section>
 ${plugGroupHtml(g)}
 <section><div class="sh"><h2>Active projects</h2><button class="lnk" onclick="projectForm({groups:['${id}']})">New</button></div>${activeProj(ps)}</section>
 ${groupMedia(g)}
 <section><div class="sh"><h2>Shared notes</h2></div>${ns.length?`<div class="ngrid">${ns.slice(0,12).map(noteCard).join('')}</div>${ns.length>12?`<button class="btn full" onclick="NF.f='shared';go('notes')">All ${ns.length} shared notes</button>`:''}`:`<div class="card emptyrow sub">Share a note in a Notes channel or from its menu to see it here.</div>`}</section>
 <section>${g.owner==='me'?`<button class="btn danger full" onclick="groupDelete('${id}')">Delete group</button>`:`<button class="btn danger full" onclick="groupLeave('${id}')">Leave group</button>`}</section></div>`}
/* typing / in a channel lists the commands of the group's plugins */
function cmdPop(g,v){const f=$('#cf');if(!f)return;let p=$('#cmdP');const t=String(v||'');if(!t.startsWith('/')||t.includes(' ')){if(p)p.remove();return}
 const q=t.slice(1).toLowerCase(),L=plugCmds(g).filter(x=>x.c.toLowerCase().startsWith(q));if(!L.length){if(p)p.remove();return}
 if(!p){p=document.createElement('div');p.id='cmdP';p.className='cmdpop';p.setAttribute('role','listbox');f.appendChild(p)}
 p.innerHTML=L.slice(0,6).map(x=>`<button type="button" role="option" data-c="${PK.esc(x.c)}">${PK.picHtml(x.pl)}<b>/${esc(x.c)}</b><span>${esc(x.pl.name)}</span></button>`).join('');
 p.querySelectorAll('[data-c]').forEach(b=>b.onclick=()=>{const i=$('#ci');i.value='/'+b.dataset.c+' ';i.focus();p.remove()})}
